// Audio adapter: the sound itself is Saltline's engine (js/sl/audio-sl.js, generated by tools/port-sl-audio.js):
// Float32 synthesis, time-sliced generation, outdoor/shed convolution reverbs crossfaded by an indoor factor,
// voice pools, compressor + soft clip, music ducking and five intensity-driven stems.
// This file translates Ga Chìm's events into Saltline's event table and keeps a small play() for one-offs.
import { createSaltlineAudio } from './sl/audio-sl.js';

class Bus {
  constructor() { this.h = new Map(); }
  on(t, f) { if (!this.h.has(t)) this.h.set(t, []); this.h.get(t).push(f); }
  emit(t, p) { for (const f of this.h.get(t) || []) f(p); }
}

// old one-shot names -> Saltline sound table entries
const ALIAS = {
  rifle: 'rifle_shot', click: 'ui_click', thud: 'impact_concrete', ping: 'impact_metal', shell: 'shell_bounce',
  step_concrete: 'step_concrete', step_asphalt: 'step_concrete', step_gravel: 'step_concrete', step_water: 'step_water', step_metal: 'step_metal',
  boom: 'explosion', hurt: 'hurt', screech: 'alert', servo: 'telegraph', thunder: 'thunder',
};
const SL_TYPE = { drone: 'gull', crawler: 'hound' };

export class Audio {
  constructor(G) {
    this.G = G; this.bus = new Bus(); this.engine = null; this.vol = 0.9; this.ready = false;
    this.proxies = new WeakMap(); this.lastState = null;
    if (G.params.noaudio) return;
    const self = this;
    const shim = {
      events: this.bus,
      get camera() { return G.camera; },
      level: { interiorBoxes: [], objectives: [] },
      ground: { isPuddle: (x, z) => !!(G.puddleAt && G.puddleAt({ x, y: 0, z })) },
      enemies: { list: [] },
      game: { get state() { return self.slState(); } },
    };
    this.shim = shim;
    createSaltlineAudio(shim).then((eng) => {
      this.engine = eng; this.ready = true; eng.setVolume(this.vol);
      if (eng.ready) eng.ready.then(() => { this.synthDone = true; });
    }).catch((e) => { console.error('[audio] engine failed to start', e); G.errors.push('audio: ' + e.message); });
  }
  // called once the level and enemies exist
  bind() {
    if (!this.shim) return;
    const G = this.G, E = G.events, B = this.bus;
    this.shim.level.interiorBoxes = G.level.dryZones.map((z, i) => {
      const iz = G.U.uIndoor.value[i]; if (!iz || !(iz.z > 0)) return null;
      return { min: { x: iz.x - iz.z, y: 0, z: iz.y - iz.w }, max: { x: iz.x + iz.z, y: z.h, z: iz.y + iz.w } };
    }).filter(Boolean);
    const proxy = (e) => {
      if (!this.proxies.has(e)) this.proxies.set(e, { type: SL_TYPE[e.type] || 'hound', get pos() { return e.pos; }, get alive() { return e.alive !== false && !e.dead; } });
      return this.proxies.get(e);
    };
    const spawn = G.enemies.spawn.bind(G.enemies);
    G.enemies.spawn = (type, p, ...rest) => { const e = spawn(type, p, ...rest); if (e && type !== 'raider') B.emit('enemy:spawn', { enemy: proxy(e) }); return e; };
    E.on('player:hit', (h) => B.emit('player:hit', { amount: h.dmg }));
    E.on('enemy:dead', ({ e }) => {
      if (e.type === 'raider') this.play('hurt', { pos: e.pos, pitch: 0.7 });
      else B.emit('enemy:killed', { enemy: proxy(e), type: SL_TYPE[e.type], pos: e.pos });
    });
    E.on('enemy:alert', (e) => { if (e.type === 'raider') this.play('reload_bolt', { pos: e.pos, gain: 0.7 }); else B.emit('enemy:alert', { enemy: proxy(e) }); });
    E.on('crawler:tell', (e) => B.emit('enemy:telegraph', { enemy: proxy(e), type: 'hound', time: 0.4, melee: true }));
    E.on('drone:tell', (e) => B.emit('enemy:telegraph', { enemy: proxy(e), type: 'gull', time: 0.55 }));
    E.on('raider:tell', (e) => this.play('reload_bolt', { pos: e.pos, gain: 0.6, pitch: 0.9 }));
    E.on('crawler:step', (p) => B.emit('enemy:step', { pos: p, type: 'hound', speed: 3 }));
    E.on('raider:step', (p) => this.play('step_concrete', { pos: p, gain: 0.45 }));
    E.on('drone:shot', (s) => { B.emit('enemy:fire', { type: 'gull', pos: s.from }); this.enemyImpact(s); });
    E.on('raider:shot', (s) => { this.play('rifle_shot', { pos: s.from, gain: 0.75, pitch: 1.06 }); this.enemyImpact(s); });
    E.on('drone:crash', (e) => B.emit('explosion', { pos: e.pos, size: 0.6 }));
  }
  enemyImpact(s) {
    const d = s.to.clone().sub(s.from).normalize();
    this.bus.emit('impact', { from: 'enemy', point: s.to, dir: d, surface: this.G.puddleAt && this.G.puddleAt(s.to) ? 'water' : 'concrete' });
  }
  slState() {
    const s = this.G.game ? this.G.game.state : 'title';
    return s === 'complete' ? 'complete' : s;
  }
  emit(name, data) { this.bus.emit(name, data || {}); }
  start() { if (this.engine) this.engine.resume(); }
  play(name, o = {}) {
    if (!this.engine) return;
    const n = ALIAS[name] || name;
    const opts = { gain: o.gain ?? o.vol ?? 1, pitch: o.pitch ?? o.rate ?? 1 };
    if (o.pos) opts.pos = { x: o.pos.x, y: o.pos.y, z: o.pos.z };
    if (o.delay) opts.delay = o.delay;
    try { this.engine.play(n, opts); } catch (e) { console.error('[audio] play ' + n, e); }
  }
  update(dt) {
    if (!this.engine) return;
    const st = this.slState();
    if (st !== this.lastState) { this.lastState = st; this.bus.emit('game:state', { state: st }); }
    this.engine.update(dt);
  }
  setVolume(v) { this.vol = v; if (this.engine) this.engine.setVolume(v); }
}
